files.content:
* {
  box-sizing: border-box;
}

html {
  block-size: 100%;
}

body {
  display: grid;
  grid-auto-rows: min-content;
  align-content: center;
  place-items: center;
  gap: 50px;
  margin: 0;
  font-family: 'Open Sans', sans-serif;
  font-size: 14px;
  background-color: #000;
  block-size: 100%;
}

button {
  border: 1px solid #fff;
  padding: 10px 65px;
  color: #fff;
  font-family: inherit;
  font-weight: 800;
  font-size: inherit;
  text-transform: uppercase;
  background-color: transparent;
}

button:hover {
  box-shadow: inset 0 0 0 100px rgb(255 255 255 / 0.15);
  cursor: pointer;
}

button:focus {
  outline: 2px solid #fff;
  outline-offset: 0;
}

button[disabled] {
  opacity: 0.6;
  pointer-events: none;
}

.lights {
  display: flex;
  gap: 20px;
}

.light {
  --color: #fff;

  box-shadow: 0 0 15px 3px currentColor;
  color: var(--color);
  background-color: currentColor;
  inline-size: 80px;
  block-size: 80px;
}

._active .light {
  animation: change-color 0.5s linear forwards;
}

.light:nth-child(2) {
  animation-delay: 1s;
}

.light:nth-child(3) {
  animation-delay: 2s;
}

@keyframes change-color {
  to {
    --color: #fd24af;
  }
}
